message.content:
{
  "maturity": "initial",
  "focalEvent": {
    "label": "Instrument-air pressure loss in RHOB area during maintenance preparation for WO-527.",
    "detail": "At approximately 10:00 AM on May 20, 2024 (Turn 2), an air-low indication occurred at the RHOB receiving station while crew U-A/U-B were preparing a boundary. Work was paused until pressure restored around 10:07 AM.",
    "status": "supported",
    "sourceIds": [
      "incident-description#1",
      "24ec1587-92e9-4320-82c2-30368d834f1d#1"
    ],
    "specialistIds": []
  },
  "nodes": [
    {
      "type": "condition",
      "label": "Crew U-A/U-B held current operating qualifications at shift start.",
      "detail": "Personnel codes are fictional; no actual employee records reproduced. Qualification status is recorded but not observed performance on the job.",
      "status": "supported",
      "sourceIds": [
        "7e69d300-c57e-40a8-bb37-35a61073ff33#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Maintenance acceptance signature was not yet signed at notification time.",
      "detail": "Work-boundary release pending; maintenance receiver M-A had not accepted the boundary when air loss occurred.",
      "status": "supported",
      "sourceIds": [
        "eaee59fe-70f4-4876-a21d-780814412078#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Temporary instruction attachment field was blank at issue time.",
      "detail": "No temporary instruction attached to work package cover; ECP-1SC-04 revision 3 issued but no approved temp instruction for this specific boundary change or routing update.",
      "status": "supported",
      "sourceIds": [
        "eaee59fe-70f4-4876-a21d-780814412078#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Area directory (IA-D01) does not establish valve positions or pressure availability at any given time.",
      "detail": "Directory is a location index only; cannot confirm if valves were open/closed or which path was active when loss occurred.",
      "status": "supported",
      "sourceIds": [
        "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Daily work briefing contained no valve-by-valve content.",
      "detail": "Briefing topic line read '1SC dryer work and RHOB service coordination' but did not list specific valves or routing changes affecting the boundary.",
      "status": "supported",
      "sourceIds": [
        "7e69d300-c57e-40a8-bb37-35a61073ff33#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "No evidence crew received recent change briefing or saw specific configuration drawing used.",
      "detail": "Training extract does not state which configuration drawing the crew saw; no interview concerning fatigue, workload or individual intent included.",
      "status": "unknown",
      "sourceIds": [
        "7e69d300-c57e-40a8-bb37-35a61073ff33#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Point register maps signals but does not establish state of any distribution valve.",
      "detail": "Register IA-P02 shows P-U and P-R points, AL-44 alarm mapping; explicitly states it does not prove every supply disturbance appears in selected sample export or identify intermediate valves.",
      "status": "supported",
      "sourceIds": [
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "RHOB requested Utilities attendance at 10:00; work paused by 10:02.",
      "detail": "Shift log shows RHOB entry 'Air-low indication... Requested Utilities attendance' followed by Utilities entry 'Work paused. RHOB service issue under review.'",
      "status": "supported",
      "sourceIds": [
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Local indication P-R normally shows normal pressure band; upstream P-U remained stable at 6.9 bar.",
      "detail": "Shift log notes morning check showed local air indication in normal band; point register excerpt implies P-U stability while P-R dropped, though exact values not captured continuously.",
      "status": "unknown",
      "sourceIds": [
        "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Potential unrecorded service-routing change or undocumented valve state created a unique hazard scenario.",
      "detail": "Hypothesis that an unrecorded routing change occurred; no evidence confirms such event actually happened. Absence of record does not prove occurrence.",
      "status": "unknown",
      "sourceIds": [
        "0ff450fe-49da-4c67-8b42-35a449fdad35c#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Communication breakdown between Utilities and RHOB may have contributed to delayed response.",
      "detail": "Hypothesis that coordination was impaired; evidence shows request at 10:00 and pause by 10:02, but no record indicates delay beyond normal steps or communication failure.",
      "status": "unknown",
      "sourceIds": [
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Transient nature of air pressure loss suggests possible upstream or distribution system issue rather than equipment failure at receiving end.",
      "detail": "Hypothesis based on transient event; records do not establish where interruption began (source vs. distribution). Transient nature alone does not support this inference without additional evidence.",
      "status": "unknown",
      "sourceIds": [
        "incident-description#1"
      ],
      "specialistIds": []
    }
  ],
  "questions": [
    {
      "intent": "Determine whether an unrecorded service-routing change or undocumented valve state actually occurred at the time of the incident.",
      "text": "Request the latest configuration drawing revision and any field-change logs for the instrument-air distribution system covering May 20, 2024. Specifically ask: Was there a documented routing change affecting RHOB receiving header H-R between shift start (07:00) and air loss (~10:00)? If yes, was it communicated to Utilities operations or included in the daily briefing?",
      "rationale": "If an unrecorded change occurred, correcting record-keeping procedures could prevent recurrence. Absence of evidence currently leaves this as unknown; obtaining drawings/logs would resolve whether a physical mechanism (routing change) caused the loss.",
      "evidenceNeeded": [
        "Latest configuration drawing revision for instrument-air distribution system",
        "Field-change logs or work orders documenting valve states between 07:00 and 10:00 on May 20, 2024"
      ],
      "priority": "high","sourceIds":[],"routedTo":["isolation-loto","other-novel"]}
    ],
    "decision": {
      "summary": "The focal event (air loss) is supported by shift logs and incident description. Several conditions are confirmed: crew qualifications, unsigned maintenance acceptance, blank temporary instruction field, directory limitations, briefing content gaps, point register signal mapping limits, and communication timeline. However, the origin of pressure loss (upstream vs. distribution vs. receiving equipment), existence of an unrecorded routing change, potential communication breakdown, and upstream stability remain unknown due to missing evidence on valve states, configuration drawings, and continuous pressure data.",
      "evidenceUsed": [
        "incident-description#1",
        "24ec1587-92e9-4320-82c2-30368d834f1d#1",
        "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1",
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "7e69d300-c57e-40a8-bb37-35a61073ff33#1",
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
      ],
      "unknowns": [
        "Exact origin of pressure loss (source, distribution, or receiving equipment)",
        "Whether an unrecorded service-routing change occurred",
        "Presence/absence of communication breakdown beyond normal steps",
        "Continuous pressure data showing upstream stability vs. drop"
      ],
      "alternatives": [
        "Upstream supply interruption (e.g., header failure, valve closure)",
        "Distribution system disturbance (e.g., leak, blockage)",
        "Receiving equipment issue (e.g., dryer malfunction)"
      ],"confidence":0.65},"evidenceRequests":[
    "Request latest configuration drawing revision and field-change logs for instrument-air distribution system covering May 20, 2024.",
    "Request continuous pressure data or alarm export showing P-U and P-R values before/after air loss."
  ]
}
